const main=document.querySelector('main'),dialog=document.querySelector('dialog');let goal='취업 준비',interest='게임아트',experience='처음 시작';
function head(en,title,link,label='전체 보기'){return `<div class="section-head"><div><span class="eyebrow">${en}</span><h2>${title}</h2></div>${link?`<a class="more" href="#${link}">${label} ↗</a>`:''}</div>`}
function courseCards(list){return `<div class="course-grid">${list.map(c=>`<button class="course" data-course="${c.id}">${c.image?`<div class="course-visual"><img src="${asset(c.image)}" alt="${c.title} 과정 소개 이미지" loading="lazy"></div>`:`<div class="course-visual admission-visual ${c.id}"><span>DESIGN YOUR FUTURE</span><strong>${c.id==='game-admission'?'GAME.':'WEBTOON.'}</strong><small>나의 전공, 나의 다음 시작</small></div>`}<div class="course-body"><small>${c.en}</small><span class="arrow">↗</span><h3>${c.title}</h3><p>${c.desc}</p><div class="tags">${c.tags}</div></div></button>`).join('')}</div>`}
function workCards(list=works){return `<div class="portfolio-slots">${list.map(w=>`<button class="portfolio-slot" data-work="${w.id}">${w.image?`<img src="${asset(w.image)}" alt="${w.title}" loading="lazy">`:''}<span>${w.image?w.student:w.student+' · 등록 예정'}</span></button>`).join('')}</div><p class="sample-note">일산점 학생들의 입시 포트폴리오를 담을 공간입니다. 작품과 학생 정보는 자료 등록 후 안내합니다.</p>`}

function campusCards(){return `<div class="campus-grid">${campus.map(c=>`<button class="campus${c.image?' has-img':''}" data-campus="${c.id}">${c.image?`<div class="campus-img"><img src="${asset(c.image)}" alt="${c.title}" loading="lazy"></div>`:''}<small>${c.en}</small><b>↗</b><span class="big">${c.big}</span><h3>${c.title}</h3><p>${c.desc}</p></button>`).join('')}</div>`}
function supportCards(cls='support-links'){return `<div class="${cls}">${supports.map(s=>`<button class="support-card" data-support="${s.id}"><small>${s.en}</small><h3>${s.title} ↗</h3><p>${s.desc}</p></button>`).join('')}</div>`}
function finder(){return `<div class="finder"><h3>나에게 맞는 수업 찾기</h3><label>01. 나의 목표</label><div class="chips" data-choice="goal">${['취업 준비','대학 입시','취미·기초'].map((s,i)=>`<button class="chip ${i===0?'on':''}" aria-pressed="${i===0}">${s}</button>`).join('')}</div><label>02. 관심 분야</label><div class="chips" data-choice="interest">${['게임아트','게임개발','웹툰·웹소설'].map((s,i)=>`<button class="chip ${i===0?'on':''}" aria-pressed="${i===0}">${s}</button>`).join('')}</div><label>03. 현재 경험</label><div class="chips" data-choice="experience">${['처음 시작','기초 경험 있음','작품 제작 중'].map((s,i)=>`<button class="chip ${i===0?'on':''}" aria-pressed="${i===0}">${s}</button>`).join('')}</div><button class="button dark" id="recommend">추천 과정 확인하기 <span>↗</span></button><div id="recommendation" aria-live="polite"></div></div>`}
function faqs(){return `<div class="faq">${[['일산점에서 게임·웹툰을 처음 배워도 괜찮을까요?','처음이라면 현재 경험과 목표를 먼저 확인하고 기초부터 시작하는 방향을 상담합니다. 관심 분야에 따라 준비 방법이 달라질 수 있습니다.'],['취업 준비와 대학 입시는 어떻게 다른가요?','취업은 희망 직무에 맞는 작업물과 지원 준비가 중심입니다. 입시는 목표 대학·학과의 전형에 맞춰 실기, 포트폴리오, 면접 등 필요한 항목을 준비합니다.'],['수업 시간과 수강료는 어디서 확인하나요?','수업 시간과 수강료는 과정과 일정에 따라 달라집니다. 수강료조회 링크를 이용하거나 031-811-8551로 문의해 주세요. 상담은 09:00~22:00에 가능합니다.'],['수업 현장은 어디에서 볼 수 있나요?','캠퍼스 갤러리에서 수업과 행사 현장을, 학원 이야기에서 입시·수업 이야기를 확인할 수 있습니다.'],['일산점은 어디에 있나요? 파주·운정·김포에서도 다닐 수 있나요?','일산동구·일산서구는 물론 덕양구(화정·행신·삼송), 파주(운정·교하·금촌), 김포에서 다니실 경우 실제 이동 경로와 가능한 수업 시간을 상담에서 함께 확인해 드립니다.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}
function subhero(en,title,desc){return `<div class="wrap"><div class="subhero"><div class="breadcrumb"><a href="#home">HOME</a> / ${title}</div><span class="eyebrow">${en}</span><h1>${title}</h1><p>${desc}</p></div></div>`}
