function regionIntro(){const areas=[['일산동구','마두 · 장항 · 백석 · 정발산 · 풍산 · 식사','ilsan-game','일산게임학원'],['일산서구','주엽 · 대화 · 탄현 · 일산 · 덕이 · 킨텍스','ilsan-webtoon','일산웹툰학원'],['덕양구','화정 · 행신 · 원흥 · 삼송 · 지축','hwajeong-game','화정게임학원'],['파주','운정 · 교하 · 금촌 · 야당','unjeong-game','운정게임학원'],['김포','한강신도시 · 걸포 · 풍무 · 사우','gimpo-game','김포게임학원']];return `<section class="section region-intro">${head('Ilsan · Paju · Gimpo','일산게임학원 · 일산웹툰학원,<br>파주 · 운정 · 김포에서도.')}<p class="region-lead"><strong>SBS아카데미게임학원 일산점</strong>은 게임원화·일러스트, 3D그래픽, 게임프로그래밍, 게임기획, 웹툰·웹소설 과정과 게임·웹툰 대학입시를 안내합니다. 일산동구·일산서구는 물론 덕양구 화정, 파주 운정, 김포에서 게임학원·웹툰학원·미술학원을 찾는 분들도 목표와 일정에 맞는 수업을 상담받을 수 있습니다.</p><div class="region-grid">${areas.map(([a,d,slug,kw])=>`<a href="#${slug}"><b>${a}</b><span>${d}</span><small>${kw} 안내 ↗</small></a>`).join('')}</div></section>`}
function showcase(){const items=[['art-raccoon.webp','게임원화','캐릭터 콘셉트 일러스트'],['art-3d.webp','3D그래픽','캐릭터 모델링 · 렌더링'],['art-witch.webp','일러스트','판타지 캐릭터'],['course-webtoon.webp','웹툰','캐릭터 · 장면 연출'],['art-beach.webp','일러스트','배경 · 캐릭터 연출'],['course-art.webp','게임원화','판타지 캐릭터 일러스트'],['campus-artbook.webp','ART BOOK','아트북 · 작품집']];const card=([img,cat,t])=>`<figure class="show-item"><img src="${asset(img)}" alt="${cat} ${t}" loading="lazy"><figcaption><b>${cat}</b>${t}</figcaption></figure>`;return `<section class="section showcase">${head('Art showcase','상상이 작품이 되는 순간,<br>SBS아카데미게임학원.')}<div class="show-track" aria-label="작품 쇼케이스"><div class="show-row">${items.map(card).join('')}${items.map(card).join('')}</div></div><p class="sample-note">SBS아카데미게임학원 작품 이미지입니다.</p></section>`}
