function tuitionHtml(){return `<span class="eyebrow">TUITION</span><h2>수강료 안내</h2><p class="tui-note">SBS아카데미게임학원 일산점(학원등록번호 경기고양 제5961호)이 관할 교육지원청에 등록한 교습비입니다. 교습시간·반환 기준 등 자세한 내용은 상담 시 안내해 드립니다.</p><div class="tui-wrap"><table class="tui"><thead><tr><th>교습과목</th><th>수강료</th></tr></thead><tbody>${TUITION_A.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table><table class="tui"><thead><tr><th>교습과목</th><th>교습비</th><th>징수단위 (월,분기)</th></tr></thead><tbody>${TUITION_B.map(([a,b,c])=>`<tr><td>${a}</td><td>${b}</td><td>${c}</td></tr>`).join('')}</tbody></table></div>`}
function privacyHtml(){return `<span class="eyebrow">PRIVACY POLICY</span><h2>개인정보취급방침</h2><p>㈜에스씨에이게임일산(SBS아카데미게임학원 일산점, 이하 \"학원\")은 이용자의 개인정보를 소중히 여기며 「개인정보 보호법」 등 관련 법령을 준수합니다.</p><h3>1. 홈페이지에서 수집하는 개인정보</h3><p>이 홈페이지는 회원가입, 상담 신청서 등 개인정보를 입력받는 기능을 운영하지 않으며, 방문자의 이름·연락처 등 개인정보를 수집·저장하지 않습니다. '나에게 맞는 수업 찾기'의 선택값은 화면에 추천을 표시하는 용도로만 사용되며 저장되거나 전송되지 않습니다.</p><h3>2. 외부 서비스 이용</h3><p>상담 예약은 네이버 예약 서비스를 통해 이루어지며, 이 과정에서 입력하는 정보는 네이버의 개인정보처리방침에 따라 처리됩니다. 전화·방문 상담 시 제공하신 정보는 상담 및 수강 안내 목적으로만 이용합니다.</p><h3>3. 개인정보 보호책임자</h3><p>성명 : 곽연호 (대표자)<br>전화 : 031-811-8551<br>이메일 : rhkrdusgh@koreaedugroup.com</p><p class="tui-note">개인정보 관련 문의, 열람·정정·삭제 요청은 위 연락처로 해 주시기 바랍니다.</p>`}
function consultationInfo(){return `<section class="visit-info"><div><span class="eyebrow">VISIT & RESERVATION</span><h2>상담 · 예약 안내</h2><p><strong>SBS아카데미게임학원 일산점</strong><br>전화 031-811-8551</p><p>${BRANCH.hours}</p></div><div class="visit-actions"><a href="${BOOK.url}" target="_blank" rel="noopener" class="visit-action naver"><small>${BOOK.en}</small><b>${BOOK.label} <span>↗</span></b><p>${BOOK.note}</p></a><a href="tel:0318118551" class="visit-action"><small>PHONE</small><b>전화 031-811-8551 <span>↗</span></b><p>관심 과정과 수업 일정을 문의하세요.</p></a><a href="https://ilsan.sbsgameacademy.com/2025/customer/tuition.asp" target="_blank" rel="noopener" class="visit-action tuition"><small>TUITION</small><b>수강료조회 <span>↗</span></b><p>공식 수강료조회 페이지로 이동합니다.</p></a></div></section>`}
function localLinks(){return `<section class="local-links"><span class="eyebrow">LOCAL</span><h2>일산 · 파주 · 운정 · 김포<br>지역별 · 과목별 안내</h2><p>찾으시는 지역과 배우고 싶은 과목에 맞는 안내 페이지입니다.</p><div>${Object.entries(localGuides).map(([slug,g])=>`<a href="#${slug}">${g.keyword}</a>`).join('')}</div></section>`}
function localPage(slug){const g=localGuides[slug];const c=courses.find(x=>x.id===g.course);return `<section class="local-hero"><div class="wrap"><div class="breadcrumb"><a href="#home">HOME</a> / 지역별 · 과목별 안내 / ${g.keyword}</div><span class="eyebrow">${g.keyword} · ${g.brand}</span><h1>${g.title}</h1><p>${g.intro}</p><a class="button orange" href="${BOOK.url}" target="_blank" rel="noopener">${BOOK.cta} ↗</a><a class="button outline" href="tel:0318118551">전화 031-811-8551</a></div></section><div class="wrap page-content"><section class="section local-learning">${head('Learning guide',g.keyword+'을 알아볼 때, 먼저 살펴볼 것들')}<div class="local-topic-grid">${g.topics.map(([t,d],i)=>`<article><span>0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="section"><span class="eyebrow">FIND YOUR COURSE</span><h2 class="local-h2">관심 분야와 이어지는 학과</h2><div class="local-course">${courseCards([c])}<div><h3>${g.brand}</h3><p>목표와 현재 경험을 확인하고, ${c.title}에서 준비할 수 있는 방향을 함께 찾아보세요.</p><a href="#courses" class="more">전체 학과 살펴보기 ↗</a></div></div></section><section class="section">${head('Questions & answers',g.keyword+' 상담 전 궁금한 점')}<div class="faq local-faq">${g.faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section>${consultationInfo()}${localLinks()}</div>`}

